function tree(x,y,s=1,t=0){let c=['#729961','#91ae70','#507d56'][t%3];return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cx="7" cy="2" rx="17" ry="7" fill="#527b48" opacity=".15"/><path d="M-3 0 L-3 -20 L3 -20 L3 0" fill="#917653"/><path d="M0 -58 L-20 -26 L-11 -26 L-24 -10 Q0 0 24 -10 L11 -26 L20 -26 Z" fill="${c}"/><path d="M0 -58 L0 -4 L24 -10 L11 -26 L20 -26 Z" fill="#315b47" opacity=".18"/><path d="M0 -51 L-12 -31" stroke="#d5e5b4" stroke-width="2" opacity=".5" stroke-linecap="round"/></g>`}
function shrub(x,y,s=1){return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse rx="15" ry="6" fill="#6f9965" opacity=".15"/><circle cx="-7" cy="-5" r="7" fill="#8eb779"/><circle cx="4" cy="-7" r="10" fill="#9bc080"/><circle cx="12" cy="-3" r="6" fill="#7ca76f"/><circle cx="1" cy="-11" r="2" fill="#f5dc9c"/></g>`}
function box(x,y,w,d,h,top,front,side){return `<g transform="translate(${x} ${y})"><path d="M0 0 L${w} ${-w*.48} L${w+d} ${(-w+d)*.48} L${d} ${d*.48} Z" fill="#527547" opacity=".14" transform="translate(3 6)"/><path d="M0 ${-h} L${d} ${d*.48-h} L${d} ${d*.48} L0 0Z" fill="${front}"/><path d="M${d} ${d*.48-h} L${w+d} ${(-w+d)*.48-h} L${w+d} ${(-w+d)*.48} L${d} ${d*.48}Z" fill="${side}"/><path d="M0 ${-h} L${w} ${-w*.48-h} L${w+d} ${(-w+d)*.48-h} L${d} ${d*.48-h}Z" fill="${top}" stroke="#fff" stroke-opacity=".2"/></g>`}
