for(const [id,patch] of Object.entries({"dataasset": {"title": "数据资产化缓解“专精特新”中小企业融资约束路径研究", "status": "2025 · 金融工程毕业论文", "summary": "从年报文本构建数据资产化指标，结合企业财务面板数据检验融资约束与传导机制。", "tags": ["Panel Data", "PCA", "Fixed Effects", "Bootstrap", "文本挖掘"]}, "tax": {"title": "税收优惠政策对招商蛇口财务绩效的影响研究", "status": "2025 · 财务管理辅修毕业论文", "summary": "用财务绩效指标体系、PCA 与回归分析研究税收优惠和行业周期的关系。", "tags": ["Python", "PCA", "OLS", "Financial Analysis"]}, "allocation": {"status": "EMFRM 发表 · 独立作者", "summary": "以统一选股策略和近十年历史回测，比较等额、ROE 盈利偏好、波动率风险调整三种资金配置。", "tags": ["JoinQuant", "ROE", "Portfolio", "Backtesting"]}, "thalia": {"status": "德国选拔入选 · 企业合作硕士研究 · 在研", "summary": "在德国 HHL 交换期间经选拔入选，与 Thalia AI 与数据平台及营销业务方向合作研究 AI 技能质量闭环。", "tags": ["Design Research", "LLM-as-a-Judge", "AI Governance", "Persona Skill"]}, "ever": {"status": "历史财务分析案例", "summary": "历史财务数据中的流动性、杠杆和经营效率风险，归入财务分析而非实习成果。"}, "securities": {"title": "兴业证券研究所｜计算机与科技行业研究", "summary": "上市科技公司财务底稿、业绩跟踪、专家会议纪要、证券 IT 产业链及比特币专题学习。", "tags": ["Equity Research", "Financial Modeling", "Expert Interview", "FinTech", "Bitcoin Research"]}, "vc": {"title": "前海维港创投｜科技投资研究", "summary": "科技企业立项研究、数据安全产品与竞品分析、商业尽调和财务分析框架。"}}))Object.assign(projects.find(p=>p.id===id),patch);

projects.push(...[{"id": "hundsun", "title": "恒生电子｜2024 中报与业务分部研究", "cats": ["finance"], "status": "兴业证券实习 · 公开资料分析", "summary": "由营收、利润、八个业务板块、费用结构到 AI 与信创业务进展。", "tags": ["业绩跟踪", "财务拆解", "金融科技"], "value": "从公告信息提炼经营驱动与跟踪指标。", "source": "恒生电子 2024 年中报分析底稿（公开资料整理）", "flow": ["公告", "分部收入", "利润质量", "技术进展"]}, {"id": "wondershare", "title": "万兴科技｜财务与事件跟踪底稿", "cats": ["finance"], "status": "兴业证券实习 · 工作底稿", "summary": "搭建事件、点评与市场数据三个维度的研究材料结构。", "tags": ["Excel", "财务底稿", "科技研究"], "value": "将公告和历史经营数据整理为可追踪研究底稿。", "source": "万兴科技底稿0513.xlsx；仅展示工作结构", "flow": ["事件整理", "财务数据", "同比计算", "研究跟踪"]}, {"id": "streamax", "title": "锐明技术｜企业调研与基本面更新", "cats": ["finance"], "status": "兴业证券实习 · 2024.08", "summary": "企业交流后形成结构化调研纪要，围绕商用车智能化、海外市场与经营风险提炼问题。", "tags": ["专家调研", "商业分析", "技术路线", "纪要"], "value": "将非结构化交流信息提炼为可以继续验证的研究问题。", "source": "2024.08.01 会议纪要及基本面更新（仅展示研究框架）", "flow": ["业务", "行业", "技术", "财务", "跟踪"]}, {"id": "brokerit", "title": "证券 IT｜交易系统与金融信息产业链", "cats": ["finance"], "status": "兴业证券实习 · 行业研究", "summary": "拆解投资者、券商、交易所之间的交易链与行情链，并跟踪信息服务生态。", "tags": ["系统架构", "产业链", "金融科技"], "value": "将复杂行业系统转化为可读的业务拓扑图。", "source": "原 PPT 图表；参考宜人智库《证券投资产业链核心企业分析》等", "flow": ["投资者", "证券公司", "交易所"]}, {"id": "bitcoin", "title": "Bitcoin｜数字资产研究学习档案", "cats": ["finance"], "status": "兴业证券实习 · 专题阅读", "summary": "实习导师提供研究报告、安排比特币专题学习；以研究问题地图呈现分析方向。", "tags": ["Bitcoin", "Digital Assets", "Research Reading"], "value": "展示对新兴数字资产研究的学习与分析框架。", "source": "本人补充的实习任务说明；原比特币报告及最终输出暂未提供", "flow": ["协议机制", "供需", "市场结构", "风险"]}]);

Object.assign(depth,{"dataasset": ["数据资产化能否缓解轻资产、高研发的专精特新企业融资约束？", ["研究动机：知识产权及数据等无形资源较难匹配传统抵押信贷体系。结合信息不对称理论和资源基础理论，分析数据资产价值被金融机构识别的条件。", "数据工程：将“小巨人”企业名单按证券代码匹配年报文本、企业财务及控制变量。词频工作簿覆盖 221 个数据资产关键词；构造年报数据资产化代理指标，避免把词频直接等同会计入表金额。名单、财务、年报与控制变量为不同底表。", "论文样本：2019—2023 年沪深 A 股和新三板；初步 623 家，筛除金融业、ST/PT、上市未满一年与缺失关键变量后，保留 368 家、1,768 个观测。连续变量双侧 1% 缩尾。上传财务底表本身是 368×5=1,840 条，不能等同最终回归样本。", "模型：FC_it = α + β DA_it + γ Controls_it + ε_it；采用主成分分析和企业固定效应，检验信贷配置、资金流动性中介机制与技术能力调节机制，Bootstrap 重抽样 5,000 次。另考察企业规模异质性与滞后影响。", "原论文结论：数据资产化与融资约束缓解相关；信贷配置与资金流动性是传导路径；高技术能力企业效果更明显。两条中介路径的报告占比为 81.67% 和 56.37%，分别来自模型，不宜相加或理解成总效应构成。"], [["名单匹配", "证券代码 × 企业认定名单"], ["文本量化", "221 词频 / DA 代理变量"], ["面板处理", "财务指标 / 控制变量 / 1% 缩尾"], ["计量识别", "PCA / 固定效应 / Bootstrap"], ["机制检验", "信贷 / 流动性 / 技术能力"], ["稳健性视角", "异质性与滞后关系"]], ["毕业答辩与论文", "数据资产化词频与财务面板底表", "传导机制和政策建议"], "论文结果来自原研究；底表图表为本次直接汇总，未重估最终回归，不将关联断言为因果。"], "tax": ["行业下行时，税收优惠能否转化为企业经营绩效？", ["研究范围：2016—2025 年房地产税收政策梳理，2016—2023 年招商蛇口财务及行业指标，区分直接激励和行业衰退阶段缓冲作用。", "四维指标体系：盈利能力（ROA、ROE、营业净利率）；偿债能力（流动比率、资产负债率）；营运能力（存货周转率、总资产周转率）；发展能力（营业收入增长率、总资产增长率）。", "Python 实现：StandardScaler 标准化；对四组财务指标分别 PCA；按累计贡献率和特征值规则筛选主成分，再按解释方差贡献率加权合成 F_盈利、F_偿债、F_运营、F_发展。statsmodels OLS 检查税收优惠强度与各维度关系。", "缓冲效应：计算绩效、税收优惠及对应行业指标的变化率，先运行基础模型，再加入行业趋势变量。论文认为行业下行时政策更多发挥缓冲作用，不能直接改变高杠杆结构。", "方法反思：仅 8 个年度样本，回归检验统计功效有限；PCA 分数方向与负向指标需要统一解释，标准化后跨零的 pct_change 可能不稳定。原始底表和摘要部分数值口径也有差别，下方图表以第二部分数据.xlsx 为准。"], [["数据", "8 个年度 / 13 个指标"], ["标准化", "StandardScaler"], ["降维", "PCA 四维绩效评分"], ["回归", "OLS 基础与行业控制"], ["验证", "结构性差异 / 缓冲效应"]], ["财务绩效.py 原始分析脚本", "第一与第二部分财务数据", "学位论文与研究结论"], "使用原底表做交互图；未把单公司小样本关联包装成政策因果识别。"], "allocation": ["保持选股不变，资金分配规则是否改变收益与风险？", ["研究发表于 EMFRM（简历记载），独立作者。研究使用聚宽 JoinQuant，回测区间 2015.01.01—2024.10.18，沪深 300 为基准，统一选股策略使用 ROE 排序；原论文设定投资金额 1,000,000、20 只持仓。", "等额法：每只持仓分配 C/N，基准易实现、忽略个体盈利与风险差异。盈利偏好法：按 ROE 名次计算原始权重 N−rank，再归一化为资金比例；原文未明确名次从 0 或 1 开始，展示以第 1 名为 1 的约定，并允许切换。", "风险调整法：以过去 n 日收盘价标准差衡量风险，低波动股票分配更高权重。原论文公式有归一化记号歧义，交互采用解释性复原 w_i=(1/σ_i)/Σ(1/σ_j)，并非恢复原始策略代码。n 的确切设置及每日交易数据目前缺失。", "结果：表 1 的三组策略收益分别为 523.37%、568.84%、544.03%；盈利偏好组 Sharpe=0.667、Sortino=0.759，风险调整组最大回撤=47.50%。原论文正文另一处写 48.50%，本页明确采用表 1。表中收益标签为 Strategy Return，未将其解释为年化。", "研究边界：同一选股策略、单一市场区间，无法排除样本偏差、交易成本影响或过拟合。原回测图片和结果表仍可展示，但缺少逐日净值、交易明细与源代码，不能伪造新的收益曲线或声称完整复现。"], [["共同基础", "统一 ROE 选股 / 20 只持仓"], ["等额", "w_i=1/N"], ["盈利偏好", "w_i∝N−rank_i"], ["风险调整", "w_i∝1/σ_i（复原解释）"], ["收益", "Strategy Return / Excess Return"], ["风险", "Sharpe / Sortino / Max Drawdown"]], ["原英文论文 Fig.1–4", "原表 1 回测指标", "可交互资金权重重构演示"], "发表状态按简历，未补正式 DOI。历史原图与表保留；交互为假设输入，不是投资建议。"], "thalia": ["从业务部门试用到可度量的企业 AI 质量工程。", ["项目经历：在德国 HHL 莱比锡商学院学术交换期间，经选拔入选 Thalia 企业合作硕士课题（本人补充）。研究方向为 AI Skills and Agents 的迭代评测与持续开发，连接 AI 与数据平台部和营销部。", "真实业务问题：企业内部 AI 技能从 Alpha 转向持续迭代，人工反馈耗时、质量标准难以量化、提示词或模型升级可能引发静默退化。业务专家判断是稀缺资源，应将人工集中在关键样本。", "应用：Persona Skill 用已核准的客群描述支持营销方案初筛、画像视角问答和反馈；不应虚构画像特征，也不能替代真实市场调研。以画像忠实度、论证质量、来源可追溯性、无幻觉四维设计量规。", "研究方案：现状分析与业务访谈 → 固定测试集及反馈管理 → 确定性校验、LLM-as-a-Judge、人工抽检 → 原型开发及版本追溯 → 效果验证。重点监控裁判模型的长度、位置、自我风格偏差及标准漂移。", "验证目标：测量裁判与专家的一致性、输出质量、迭代周期、专家与开发工时；建立责任归属和维护模型，探索推广至其他技能的可行性。当前为在研方案，结果与实际平台权限不对外展示。"], [["发现", "业务痛点与现状梳理"], ["定义", "四维评分标准 / 测试集"], ["自动化", "规则 + LLM Judge"], ["校准", "专家抽检 / 一致性"], ["改进", "反馈回填 / 回归测试"], ["治理", "版本 / Ownership / 审计证据"]], ["德国选拔入选的企业合作研究", "硕士论文研究方案", "拟交付：参考流程、原型、校准量规与可替换测试集", "拟验证：人机一致性、质量、工时、版本回归"], "在研，网站不公开内部画像、平台数据或声称已验证效果；选拔经历为本人提供。"], "securities": ["把技术研究、财务分析和企业交流变成可交付的证券研究材料。", ["2024.07—09，兴业证券研究所计算机/科技组，研究分析师实习生。按简历及新增材料，围绕软件、金融科技、商用车智能化及数字资产开展研究支持。", "恒生电子：中报底稿从公开公告整理收入、归母利润、扣非利润、分部业务、毛利率、三费率及 AI/信创进展。万兴科技：按事件、点评、市场数据分类形成跟踪工作簿。", "锐明技术：参与企业业务交流的研究支持，整理 2024.08.01 会议纪要、基本面更新与 Q&A。公开作品只展示业务和风险分析框架，不披露未经授权的具体会议发言及预测。", "证券 IT：对照行业研报梳理交易、行情、信息服务体系，完成柜台交易流程图。导师还布置比特币专题阅读，原报告未提供，单列为研究学习任务而非已完成报告。"], [["公告", "财务与经营数据"], ["企业调研", "问题 → 纪要 → 待验证事项"], ["技术拆解", "交易与行情架构"], ["市场扫描", "行业研报与数字资产阅读"]], ["恒生电子中报公开资料整理", "万兴科技跟踪底稿", "锐明技术会议纪要及基本面更新", "证券 IT 交易系统图解", "比特币研究学习任务"], "不公开内部工作簿、完整纪要及机构观点。引用他人研究报告时标注参考来源。"], "vc": ["从数据安全技术产品理解早期投资的商业化判断。", ["2024.01，前海维港创业投资基金（VC Capital），投资分析实习生。以昂楷科技为代表，研究数据安全治理产品与医疗、政务、能源等应用场景。", "按简历记载，开展 30 余家同业软硬件方案横向对标，参与商业尽职调查与万字立项研报。分析产品矩阵、客户需求、技术门槛、交付效率及行业竞争。", "研究方法包含业务、产品、市场、财务和风险分析，形成项目立项与后续验证问题；关注回款、资产负债结构、估值假设及资源预算。", "作品展示保留昂楷科技公司名称及可公开的产品研究，内部交易、非公开财务与机构判断不展示。固生堂为该实习期间的企业财务研究；恒大为独立案例，不归入本实习。"], [["01 技术", "数据治理生命周期"], ["02 市场", "细分赛道及同业对标"], ["03 商业", "客户、交付、回款"], ["04 尽调", "资料清单及风险问题"]], ["昂楷科技研究报告", "固生堂企业财务研究", "脱敏产品与竞争格局研究", "投资分析及商业提案方法"], "按简历和原报告整理，内部报告不公开；固生堂归属维港实习；恒大保持独立财务案例。"], "hundsun": ["2024H1 收入平稳，但利润同比承压，如何进一步拆解？", ["原公开资料底稿：H1 收入 28.36 亿元，同比 +0.32%；归母净利润 2,989.03 万元，同比 −93.30%；扣非归母净利润 1.36 亿元，同比 −48.81%。", "按八个分部跟踪收入及增速。财富科技服务下降，资管科技与运营机构科技服务相对增长；结合产品需求、信创进程和竞争情况继续验证。", "毛利率 71.32%，销售、管理、研发费用率分别 13.74%、13.59%、40.96%。底稿列出非经常性损益约 −1.06 亿元，需区分经营利润与金融资产公允价值变动。", "技术进展跟踪关注投研一体化、Warren Q、信创配置与交易所测试认证。此为历史公告整理，而非机构投资观点。"], [["收入", "H1 / Q2 同比"], ["结构", "八大业务板块"], ["利润", "毛利 / 费用 / 非经常损益"], ["技术", "AI / 信创 / 认证"]], ["历史中报公开数据图表", "业绩拆解与技术业务跟踪"], "历史口径来自本人工作底稿，未重新核验公告；不构成当前投资判断。"], "wondershare": ["怎样维护一家科技公司的结构化研究底稿？", ["原工作簿分为事件、点评、市场数据三个工作表。数据出处包括公司年报与 iFinD。", "将信息按时间与事件归档；用年度收入、利润、员工人数等变量计算同比，便于跟踪经营变化。", "在研究流程中将原始数据、计算、来源、待验证解释分层。原工作簿含机构材料，不提供下载或未授权截图；本页展示可公开的数据处理方法。"], [["事件", "事件时间线与来源"], ["点评", "年报指标 / 同比"], ["市场数据", "行情及对标变量"], ["复核", "单位 / 口径 / 公式"]], ["三工作表研究底稿结构", "财务指标同比计算方法"], "只展示工作方法，不披露原底稿内部信息。"], "streamax": ["企业访谈如何转化为下一步研究问题？", ["2024 年 8 月企业交流材料覆盖业务与行业、技术路线、海外渠道、财务表现、研发、应收账款和供应链。", "技术分析主线：从定位、视频取证、全车智能到 AI，考察商用车主动安全系统、产品与解决方案如何变化。", "商业研究框架：政策与技术驱动需求；分市场、分产品跟踪定价、交付、毛利和回款；识别国际供应链、本地化及研发投入风险。", "将纪要中的观点列为待核验假设，回到公开公告验证，避免直接把会议口头预测作为事实。"], [["技术", "定位 → 视频 → 主动安全 → AI"], ["市场", "国内 / 海外 / 产品应用"], ["经营", "价格、毛利、回款"], ["风险", "供应链、研发、政策"]], ["企业调研纪要（不公开全文）", "基本面更新 Q&A（仅框架）", "后续研究问题清单"], "不公开参会人、未授权发言、非公开预测或经营数字。"], "brokerit": ["如何把券商交易与行情系统画成端到端业务图？", ["交易链：投资者客户端经网上交易或 PB 系统到券商柜台，再经报盘前置与交易所接口进入交易主机。", "行情链：交易所行情系统经行情前端到券商或信息商，再向投资者行情客户端提供信息。", "研究生态：核心业务系统、网上交易/行情、门户社区、数据终端、智能投研、智能策略与投顾；原参考报告对比东方财富/同花顺、富途/老虎等。"], [["入口", "投资者交易终端"], ["券商", "柜台 / PB / 网上交易"], ["交易所", "报盘 / 撮合 / 行情"], ["行业", "软件 / 数据 / 辅助决策"]], ["本人制作的证券 IT 图表", "参考研报中的产业链框架"], "参考研报为宜人智库等第三方资料，不是本人撰写；历史研究，不代表当前竞争格局。"], "bitcoin": ["如何形成数字资产行业研究的基本框架？", ["实习期间导师提供研究报告并布置比特币研究任务（本人补充），目前没有上传该专题的原报告、代码或最终分析成果。", "可作为研究学习路径：先区分协议层、资产层、交易与托管，再理解供给机制、需求来源、流动性与市场结构。", "风险问题清单：价格波动、交易场所与托管风险、链上安全、监管及流动性。此框架是本次整理新增的研究导览，不表示过去已完成全部分析。"], [["协议", "共识 / 交易验证"], ["供需", "供给机制 / 使用需求"], ["生态", "交易、托管、基础设施"], ["风险", "波动、合规、操作风险"]], ["导师布置的专题阅读", "研究导览（本次整理）"], "未提供原报告或独立研究结果；不编造实习成果，不涉及实时行情或投资建议。"]});

