const isMulti=document.body.dataset.multi==='1',root=document.body.dataset.root||'./';
function loadSet(k){try{return new Set(JSON.parse(localStorage.getItem(k)||'[]'))}catch{return new Set()}}
function saveSet(k,v){try{localStorage.setItem(k,JSON.stringify([...v]))}catch{}}
const stamps=loadSet('hayley-stamps-v3'), favorites=loadSet('hayley-favorites-v3'), critters=loadSet('hayley-critters-v3');
function routeUrl(r){return isMulti?root+(r==='map'?'index.html':r+'.html'):'#/'+r}
function go(r){if(isMulti){location.href=routeUrl(r)}else{if(location.hash==='#/'+r)showRoute(r);else location.hash='/'+r}}
function currentRoute(){return isMulti?document.body.dataset.route:(location.hash.replace(/^#\/?/,'')||'map')}
function rememberStation(id){stamps.add(id);saveSet('hayley-stamps-v3',stamps)}
let toastTimer;function toast(t){let e=$('forestToast');e.textContent=t;e.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.add('hidden'),2500)}
function toggleFav(id){let add=!favorites.has(id);add?favorites.add(id):favorites.delete(id);saveSet('hayley-favorites-v3',favorites);toast(add?'🍓 已收藏到旅行手账':'已从收藏移除');document.querySelectorAll('[data-fav="'+id+'"]').forEach(b=>{b.classList.toggle('on',add);b.textContent=add?'♥':'♡';b.setAttribute('aria-pressed',String(add))});if(currentRoute()==='favorites')renderCards()}
