$('projectCount').textContent=String(projects.length).padStart(2,'0');$('about').querySelector('h2').textContent='Hayley Wu · 金融 × AI × 商业智能';$('about').insertAdjacentHTML('beforeend',`<div><div class="eyebrow">FEATURED POSTCARD</div><h2>德国 · HHL × Thalia</h2><p>德国交换期间经选拔入选 Thalia 企业合作硕士研究，在研方向为 AI Skills / Agents 迭代评测与治理。</p><button class="pill" id="aboutThalia">查看研究项目 ↗</button></div><div><div class="eyebrow">CAREER TRAIL</div><h2>研究、产品与数据</h2><p>从两段科技投研实习到人工智能与商业智能方向，连接业务理解与技术实现。</p><button class="pill" id="aboutCareer">职业足迹 ↗</button></div>`);$('aboutThalia').onclick=()=>go('case/thalia');$('aboutCareer').onclick=()=>go('station/intern');
